// SPDX-License-Identifier: MIT
pragma solidity 0.8.36;

/// @notice Shared failures for Hold storage, descriptors and reads. Import this
/// interface when matching revert selectors; no deployed error registry is needed.
interface IKeelHoldErrors {
    error EmptySlug();
    error EmptyBatch();
    error TooManyBatchSlugs(uint256 supplied, uint256 maximum);
    error SlugTooLarge(uint256 supplied, uint256 maximum);
    error SlugMissing(bytes32 slugId);
    error EmptyObject();
    error TooManyChildren(uint256 supplied, uint256 maximum);
    error InvalidDigest();
    error InvalidByteLength();
    error InvalidMediaType();
    error InvalidDescriptor();
    error ObjectMissing(bytes32 objectId);
    error WrongObjectKind();
    error SliceOutOfBounds();
    error ReadDepthExceeded();
    error CompressedObjectReadUnsupported();
    error ObjectReadLengthMismatch();
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.36;

interface IKeelHoldSeal {
    /// @dev One slot. Native-currency amounts are wei, not a live USD oracle.
    struct SealFees {
        uint64 perChunkWei;
        uint64 baseSealWei;
        uint64 stepSealWei;
        uint32 chunksPerStep;
        uint32 revision;
    }

    /// @dev Two slots. The intent ID commits its payer; only the named executor
    /// can consume the allowance or finish the committed object.
    struct WeldIntent {
        address executor;
        uint32 slugCount;
        uint32 remainingSlugs;
        bool complete;
        bytes32 objectId;
    }

    error InvalidSealFees();
    error StaleSealFeeRevision(uint32 supplied, uint32 current);
    error IncorrectSealFee(uint256 supplied, uint256 required);
    error SealRequired(bytes32 objectId);
    error IntentRequired();
    error InvalidIntent();
    error IntentAlreadyOpened(bytes32 intentId);
    error UnauthorizedUploader();
    error IntentComplete();
    error SlugAllowanceExceeded(uint256 supplied, uint256 remaining);
    error IntentCountMismatch(uint256 actual, uint256 planned);

    event SealFeesConfigured(bytes32 packedFees);
    event FeeExemptionSet(address indexed account, bool exempt);
    event WeldInitiated(
        bytes32 indexed intentId,
        bytes32 indexed objectId,
        address indexed payer,
        address executor,
        uint32 slugCount,
        uint256 fee
    );
    event ObjectSealed(bytes32 indexed objectId, bytes32 indexed intentId, uint64 slugCount);

    function sealFees() external view returns (SealFees memory);
    function configureSealFees(
        uint32 expectedRevision,
        uint64 perChunkWei,
        uint64 baseSealWei,
        uint64 stepSealWei,
        uint32 chunksPerStep
    ) external;
    function setFeeExempt(address account, bool exempt) external;
    function feeExempt(address account) external view returns (bool);
    function isSealed(bytes32 objectId) external view returns (bool);
    function sealRequired(bytes32 objectId) external view returns (bool);
    function quoteWeld(uint32 slugCount, address payer) external view returns (uint256 fee, uint32 revision);
    function weldIntentId(address payer, bytes32 objectId, address executor) external pure returns (bytes32);
    function weldIntent(bytes32 intentId) external view returns (WeldIntent memory);
    function initWeld(bytes32 objectId, uint32 slugCount, address executor, uint32 expectedFeeRevision)
        external
        payable
        returns (bytes32 intentId);
    function castSlugFor(bytes32 intentId, bytes calldata data) external returns (bytes32 slugId, address pointer);
    function castSlugsFor(bytes32 intentId, bytes[] calldata payloads)
        external
        returns (bytes32[] memory slugIds, address[] memory pointers);
    function sealObject(bytes32 intentId) external;
    function feeTreasury() external view returns (address);
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.36;

interface IKeelHoldHarness {
    struct HarnessFees {
        uint64 registrationWei;
        uint32 revision;
    }

    error InvalidHarness();
    error HarnessRegistrationRequired(bytes32 objectId, address renderer);
    error StaleHarnessFeeRevision(uint32 supplied, uint32 current);
    error IncorrectHarnessFee(uint256 supplied, uint256 required);

    event HarnessFeesConfigured(uint64 registrationWei, uint32 revision);
    event HarnessRegistered(bytes32 indexed objectId, address indexed renderer, address indexed payer, uint256 fee);

    function harnessFees() external view returns (HarnessFees memory);
    function configureHarnessFees(uint32 expectedRevision, uint64 registrationWei) external;
    function harnessRegistered(bytes32 objectId, address renderer) external view returns (bool);
    function quoteHarness(bytes32 objectId, address renderer, address payer)
        external
        view
        returns (uint256 fee, uint32 revision);
    function registerHarness(bytes32 objectId, address renderer, uint32 expectedRevision) external payable;
    function requireHarness(bytes32 objectId, address renderer) external view;
}
